INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-001', 'EG', 'P2', 'OPEN', NULL, NULL, 'Evidence gap (parameter-scoped): 4 extraction(s) exist for parameter 3, but EVERY source holding one has been SUPERSEDED (evidence_sources.superseded_by_ref_id is set) and a superseded source is not gathered. Cell 3×MOB; recorded while working slug ''accessible-circulation-geometry''. Remedy: the reading exists; the document behind it was replaced. Re-extract the same parameter from the superseding source. Determination pending per §2.4.', '2026-09-16 00:00:00', 'session_2026-09-16-research-batch-08-ramp-gradient', '2026-09-16 00:00:00', 'session_2026-09-16-research-batch-08-ramp-gradient', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding", "prior_expectation") VALUES (29, 'accessible-circulation-geometry', NULL, 'EN', 1, 'co1', 'intrinsic', '(wheelchair[Title/Abstract]) AND (ramp[Title/Abstract] OR slope[Title/Abstract] OR incline[Title/Abstract]) AND (co-production[Title/Abstract] OR co-design[Title/Abstract] OR participatory[Title/Abstract] OR "lived experience"[Title/Abstract])', NULL, 'pubmed', 'scoping', 'none', 0, 0, 0, NULL, NULL, NULL, 0, 'session_2026-09-16-research-batch-08-ramp-gradient', '2026-09-16 04:55', 'GENUINE ABSENCE IN THIS INDEX, NOT A QUERY-SHAPE FAILURE, and the control is what proves it: exec for S3 below ran the identical subject terms (wheelchair propulsion x ramp/slope/incline) with the co-production clause REMOVED and returned 63. PubMed AND-chains every term, so the clause is what zeroes it. This is a fact about publication venue: Co-1 on ramp gradient is not reachable through PubMed and must be sought in DPO, housing and participatory-design venues. NOT a claim that disabled people have not produced knowledge on ramp slope.', 0, 'Near-zero in PubMed. Co-1 on ramp gradient, if it exists, sits in DPO publications, housing-design and participatory-design venues, not the indexed medical literature. Expect a well-formed zero and expect to have to say so under R14 rather than treat it as absence of the knowledge itself.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding", "prior_expectation") VALUES (30, 'accessible-circulation-geometry', NULL, 'EN', 2, 'sr_meta', 'intrinsic', '(wheelchair propulsion) AND (ramp OR slope OR incline) AND (systematic review[Publication Type] OR meta-analysis[Publication Type])', NULL, 'pubmed', 'systematic', 'none', 1, 1, 1, NULL, NULL, NULL, 0, 'session_2026-09-16-research-batch-08-ramp-gradient', '2026-09-16 04:55', 'One hit, admitted as REF-00984. Prior held: it is a review of wheelchair SKILLS TESTS, in which ascending slopes is one skill among several; it states no gradient.', 0, 'A small number of reviews on wheelchair propulsion biomechanics exist; ramp slope appears inside them as one condition among several rather than as the review subject. Expect 0-3 hits and expect none to state a recommended gradient.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding", "prior_expectation") VALUES (31, 'accessible-circulation-geometry', NULL, 'EN', 1, 'clinical', 'high_control', '(wheelchair propulsion[Title/Abstract]) AND (ramp[Title/Abstract] OR slope[Title/Abstract] OR incline[Title/Abstract])', NULL, 'pubmed', 'systematic', 'none', 63, 25, 3, NULL, NULL, NULL, 0, 'session_2026-09-16-research-batch-08-ramp-gradient', '2026-09-16 04:55', 'Prior held exactly: every admitted source treats slope as an independent variable, none states a recommended maximum. Also serves as the CONTROL for the S1 Co-1 zero: identical subject terms, co-production clause removed, 63 results.', 0, 'A handful of small-n laboratory biomechanics studies, most measuring shoulder load, kinematics or EMG across a slope range. Expect slope to appear as an INDEPENDENT VARIABLE (a range) far more often than as a recommended maximum.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding", "prior_expectation") VALUES (32, 'accessible-circulation-geometry', NULL, 'EN', 1, 'clinical', 'lower_control', '(wheelchair[Title/Abstract]) AND (ramp[Title/Abstract] OR slope[Title/Abstract]) AND (injury[Title/Abstract] OR tip[Title/Abstract] OR fall[Title/Abstract] OR accident[Title/Abstract] OR barrier[Title/Abstract] OR inaccessible[Title/Abstract])', NULL, 'pubmed', 'scoping', 'none', 67, 20, 0, NULL, NULL, NULL, 0, 'session_2026-09-16-research-batch-08-ramp-gradient', '2026-09-16 04:55', 'HARM LEG, 0 admitted on this pass and that is not a null result: the 20 screened overlap heavily with S3 rather than forming a distinct harm literature, and the distinctly on-harm hits are about wheelchair tips/falls generally, not about GRADIENT as the cause. Deferred to a dedicated harm pass rather than admitted thinly here.', 0, 'Thinner than S3, and what exists will report inadequacy of built ramps rather than a number. Capturing it is the point: R7 makes failure first-class, not a by-product.');
