INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (11, 'REF-00985', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, NULL, NULL, 'range', '0-4.8', 'degrees', 'the inclination of which varied between (0° to 4.8°)', 'Abstract', NULL, 'measurement_primary', 'REF-00985', NULL, 'instrumented_physical_measurement', 'manual_self_propelled', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'FIGURE-ROLE IS finding, NOT claim: 0-4.8 deg is the range the study TESTED AT, not a gradient it recommends. The source measures the EFFECT of slope (articular discomfort rising 14 to 36%) and states no design value. Grading this ''claim'' would let the engine anchor a determination on an experimental condition.', '2026-09-16 04:58', 'session_2026-09-16-research-batch-08-ramp-gradient', '2026-09-16 04:58', 'session_2026-09-16-research-batch-08-ramp-gradient', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (12, 'REF-00983', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, NULL, NULL, 'range', '3.5-15', 'degrees', 'propelled a MWC on ramps of slope 3.5°, 9.5° and 15°', 'Abstract', NULL, 'measurement_primary', 'REF-00983', NULL, 'instrumented_physical_measurement', 'manual_self_propelled', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'finding, NOT claim: these are the slopes TESTED, not a recommended gradient. The source''s own conclusion is directional -- ''imperative that bus operators minimize ramp slope'' -- and names no permitted value. Population is able-bodied proxies (n=7, no propulsion experience), graded PROXY.', '2026-09-16 04:58', 'session_2026-09-16-research-batch-08-ramp-gradient', '2026-09-16 04:58', 'session_2026-09-16-research-batch-08-ramp-gradient', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (13, 'REF-00986', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, NULL, NULL, 'absent', NULL, NULL, 'wheelchair propulsion at different speeds and inclines, ascending and descending ramps', 'Abstract', NULL, 'measurement_primary', 'REF-00986', NULL, 'instrumented_physical_measurement', 'manual_self_propelled', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'absent-confirmed', NULL, 'ABSENT IS THE HONEST GRADE AND IT IS THE FINDING. The study measures glenohumeral load for ramp ascent/descent and never states the incline it used. Manufacturing a gradient for it is exactly what the batch-06 runbook warns against for this source. claimed_value stays NULL.', '2026-09-16 04:59', 'session_2026-09-16-research-batch-08-ramp-gradient', '2026-09-16 04:59', 'session_2026-09-16-research-batch-08-ramp-gradient', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (14, 'REF-00984', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, NULL, NULL, 'absent', NULL, NULL, 'negotiating kerbs, ascending slopes, traversing tracks', 'Abstract', NULL, 'untraced', 'REF-00984', NULL, 'stated_unmeasured', 'manual_self_propelled', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'absent-confirmed', NULL, 'The T2 synthesis leg. A review of 24 wheelchair skills tests: ascending slopes is among the most frequently included tasks, and the review states no gradient for it anywhere. That silence at T2 is itself evidence about the field.', '2026-09-16 04:59', 'session_2026-09-16-research-batch-08-ramp-gradient', '2026-09-16 04:59', 'session_2026-09-16-research-batch-08-ramp-gradient', 'finding', NULL);
